class Solution {
public:
    vector<int> recoverOrder(vector<int>& order, vector<int>& friends) {
        unordered_set<int> fs(friends.begin(), friends.end());
        vector<int> res;
        for (int x : order) if (fs.count(x)) res.push_back(x);
        return res;
    }
};

