class Solution {
    public int[] recoverOrder(int[] order, int[] friends) {
        Set<Integer> fs = new HashSet<>();
        for (int f : friends) fs.add(f);
        int[] res = new int[friends.length];
        int i = 0;
        for (int x : order) if (fs.contains(x)) res[i++] = x;
        return res;
    }
}

