class Solution {
public:
    vector<int> recoverOrder(vector<int>& order, vector<int>& friends) {
        unordered_map<int,int> rank;
        for (int i = 0; i < order.size(); i++) rank[order[i]] = i;
        sort(friends.begin(), friends.end(), [&](int a, int b){ return rank[a] < rank[b]; });
        return friends;
    }
};

c.java:
class Solution {
    public int[] recoverOrder(int[] order, int[] friends) {
        int[] rank = new int[order.length + 1];
        for (int i = 0; i < order.length; i++) rank[order[i]] = i;
        Integer[] fr = Arrays.stream(friends).boxed().toArray(Integer[]::new);
        Arrays.sort(fr, (a, b) -> rank[a] - rank[b]);
        return Arrays.stream(fr).mapToInt(Integer::intValue).toArray();
    }
}

